struct bw w = {0};
char big[129];
memset(big, 65, 129);
bw_write(&w, big, 128);
CHECK_EQ(bw_pending(&w), 64);
CHECK_EQ(w.flushes, 1);
bw_write(&w, big, 1);
CHECK_EQ(w.flushes, 2);
CHECK_EQ(bw_pending(&w), 1);

struct bw w2 = {0};
bw_write(&w2, "fallback", 8);
CHECK_EQ(bw_pending(&w2), 8);
CHECK_EQ(w2.flushes, 0);

struct bw w3 = {0};
bw_write(&w3, NULL, 4);
bw_write(NULL, "fallback", 4);
bw_write(&w3, NULL, 0);
CHECK_EQ(bw_pending(&w3), 0);
CHECK_EQ(w3.flushes, 0);
